script:
frappe.ui.form.on('Sales Invoice Item', {
    form_render(frm, cdt, cdn) {
        set_display_uom_si(frm, cdt, cdn);
    },

    item_code(frm, cdt, cdn) {
        set_display_uom_si(frm, cdt, cdn);
    },

    uom(frm, cdt, cdn) {
        set_display_uom_si(frm, cdt, cdn);
    }
});

function set_display_uom_si(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    if (!row.uom) return;

    let display = row.uom.startsWith("Meter") ? "Meter" : row.uom;

    frappe.model.set_value(cdt, cdn, "display_uom", display);
}
